/* ================================================================== */
/* constants                                                           */
/* ================================================================== */

const N_SLOTS: usize = 12;
const SIG_BLOB_LEN: usize = N_SLOTS * 65; // 780

/// The fixed-width state TAIL of the production root: `byte frozen` (2 B) +
/// `byte[8] rootNonce` (9 B). Asserted against the compiler's own layout.
const ROOT_TAIL_LEN: usize = 11;
/// 33 (byte[32] boundOrgId) + 12*33 (pubkey) + 3*9 (int) + 2 + 9.
const ROOT_STATE_LEN: usize = 33 + N_SLOTS * 33 + 3 * 9 + 2 + 9; // 467
/// 12 counting sig-ops at ONE call site + 1 succession = 13, budget 15.
const ROOT_STATIC_SIG_OPS: u64 = 13;
/// rusty-kaspa mining/src/mempool/check_transaction_standard.rs.
const MAX_STANDARD_P2SH_SIG_OPS: u64 = 15;

const COV_ROOT: Hash = Hash::from_bytes(*b"ROOTROOTROOTROOTROOTROOTROOTROOT");

const ZERO32: [u8; 32] = [0u8; 32];
const ORG_ID: [u8; 32] = [0xa7u8; 32];
const ORG_ID_B: [u8; 32] = [0xb7u8; 32];

const KAS: i64 = 100_000_000;
const ROOT_KAS: i64 = 3 * KAS;
const ROOT_MAX_FEE: i64 = 200_000;
const ROOT_FEE_PAID: i64 = 50_000;
const RECOVERY_DELAY: i64 = 1_000;
const SUCCESSION_DELAY: i64 = 2_000;

/* owner key seeds (deterministic, TEST-ONLY) */
const OWNER_SEEDS: [u8; N_SLOTS] = [0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7a, 0x7b, 0x7c];
const SUCCESSOR_SEED: u8 = 0x7f;
const OUTSIDER_SEED: u8 = 0x6f;

/* ================================================================== */
/* helpers                                                             */
/* ================================================================== */

fn kp(seed: u8) -> Keypair {
    let secp = secp256k1::Secp256k1::new();
    let sk = secp256k1::SecretKey::from_slice(&[seed; 32]).expect("seed key");
    Keypair::from_secret_key(&secp, &sk)
}
fn xonly32(k: &Keypair) -> [u8; 32] {
    k.x_only_public_key().0.serialize()
}
fn hx(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}
fn num8(v: i64) -> [u8; 8] {
    (v as u64).to_le_bytes()
}
fn leak(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}
fn load(rel: &str) -> String {
    let path = format!("{}/{rel}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path}: {e}"))
}
/// THE PRODUCTION CANDIDATE — nothing else is compiled by this suite.
fn src_root() -> &'static str {
    static S: OnceLock<&'static str> = OnceLock::new();
    S.get_or_init(|| leak(load("../../contracts/PolicyVault.v0.7-root.sil")))
}

#[derive(Clone)]
struct Template {
    prefix: Vec<u8>,
    state_len: usize,
    suffix: Vec<u8>,
    hash: [u8; 32],
}
fn template_of(c: &CompiledContract<'_>) -> Template {
    let l = c.state_layout;
    let prefix = c.script[..l.start].to_vec();
    let suffix = c.script[l.start + l.len..].to_vec();
    let h = blake2b_simd::Params::new().hash_length(32).to_state().update(&prefix).update(&suffix).finalize();
    let mut hash = [0u8; 32];
    hash.copy_from_slice(h.as_bytes());
    Template { prefix, state_len: l.len, suffix, hash }
}

fn push_redeem(script: &[u8]) -> Vec<u8> {
    ScriptBuilder::with_flags(EngineFlags { covenants_enabled: true, ..Default::default() }).add_data(script).unwrap().drain()
}
fn cov_call(c: &CompiledContract<'_>, f: &str, args: Vec<Expr<'_>>) -> Vec<u8> {
    let mut s = c
        .build_sig_script_for_covenant_decl(f, args, CovenantDeclCallOptions { is_leader: false })
        .unwrap_or_else(|e| panic!("call {f}: {e:?}"));
    s.extend_from_slice(&push_redeem(&c.script));
    s
}
fn tx_input(id: u8, sigscript: Vec<u8>, sequence: u64, budget: u16) -> TransactionInput {
    TransactionInput::new_with_mass(
        TransactionOutpoint { transaction_id: TransactionId::from_bytes([id; 32]), index: 0 },
        sigscript,
        sequence,
        ComputeCommit::ComputeBudget(ComputeBudget(budget)),
    )
}
fn cov_out(value: i64, c: &CompiledContract<'_>, auth: u16, covid: Hash) -> TransactionOutput {
    TransactionOutput {
        value: value as u64,
        script_public_key: pay_to_script_hash_script(&c.script),
        covenant: Some(CovenantBinding { authorizing_input: auth, covenant_id: covid }),
    }
}
fn cov_utxo(value: i64, c: &CompiledContract<'_>, covid: Hash) -> UtxoEntry {
    UtxoEntry::new(value as u64, pay_to_script_hash_script(&c.script), 0, false, Some(covid))
}
fn build_tx(inputs: Vec<TransactionInput>, outputs: Vec<TransactionOutput>) -> Transaction {
    Transaction::new(1, inputs, outputs, 0, SubnetworkId::default(), 0, vec![])
}
fn sign_type(tx: &Transaction, entries: &[UtxoEntry], idx: usize, k: &Keypair, ht: SigHashType) -> Vec<u8> {
    let m = MutableTransaction::with_entries(tx.clone(), entries.to_vec());
    let reused = SigHashReusedValuesUnsync::new();
    let h = calc_schnorr_signature_hash(&m.as_verifiable(), idx, ht, &reused);
    let msg = secp256k1::Message::from_digest_slice(h.as_bytes().as_slice()).unwrap();
    let mut out = k.sign_schnorr(msg).as_ref().to_vec();
    out.push(ht.to_u8());
    out
}
/// The canonical abstaining slot: 64 zero bytes + the SIGHASH_ALL gate byte.
/// It passes the 0x01 gate and FAILS verification, so it counts 0.
fn placeholder_slot() -> Vec<u8> {
    let mut v = vec![0u8; 64];
    v.push(0x01);
    v
}

/* ================================================================== */
/* the production root covenant                                        */
/* ================================================================== */

#[derive(Clone, PartialEq, Debug)]
struct RootState {
    org_id: [u8; 32],
    owners: [[u8; 32]; N_SLOTS],
    owner_m: i64,
    emergency_k: i64,
    recovery_m: i64,
    frozen: i64,
    nonce: i64,
}
impl RootState {
    /// Active slots 0..n filled from OWNER_SEEDS, the rest sentinel-zero.
    fn with(n: usize, m: i64, k: i64, r: i64) -> RootState {
        let mut owners = [ZERO32; N_SLOTS];
        for (i, o) in owners.iter_mut().enumerate().take(n) {
            *o = xonly32(&kp(OWNER_SEEDS[i]));
        }
        RootState { org_id: ORG_ID, owners, owner_m: m, emergency_k: k, recovery_m: r, frozen: 0, nonce: 0 }
    }
    fn advanced(&self) -> RootState {
        RootState { nonce: self.nonce + 1, ..self.clone() }
    }
}

#[derive(Clone)]
struct RootTemplate {
    recovery_delay: i64,
    successor_pk: [u8; 32],
    succession_delay: i64,
    max_fee: i64,
}
impl Default for RootTemplate {
    fn default() -> Self {
        RootTemplate {
            recovery_delay: RECOVERY_DELAY,
            successor_pk: xonly32(&kp(SUCCESSOR_SEED)),
            succession_delay: SUCCESSION_DELAY,
            max_fee: ROOT_MAX_FEE,
        }
    }
}

/// Exact-live-state compilation: the state values ARE constructor arguments in
/// this covenant, so no source templating is needed.
fn compile_root(s: &RootState, t: &RootTemplate) -> CompiledContract<'static> {
    let mut args: Vec<Expr<'static>> = vec![Expr::bytes(s.org_id.to_vec())];
    for o in s.owners.iter() {
        args.push(Expr::bytes(o.to_vec()));
    }
    for v in [s.owner_m, s.emergency_k, s.recovery_m] {
        args.push(Expr::int(v));
    }
    args.push(Expr::byte(s.frozen as u8));
    args.push(Expr::bytes(num8(s.nonce).to_vec()));
    args.push(Expr::int(t.recovery_delay));
    args.push(Expr::bytes(t.successor_pk.to_vec()));
    args.push(Expr::int(t.succession_delay));
    args.push(Expr::int(t.max_fee));
    compile_contract(src_root(), &args, CompileOptions::default()).unwrap_or_else(|e| panic!("compile production root: {e:?}"))
}

const ROOT_SLOT_NAMES: [&str; N_SLOTS] =
    ["owner1", "owner2", "owner3", "owner4", "owner5", "owner6", "owner7", "owner8", "owner9", "owner10", "owner11", "owner12"];

fn root_state_arg(s: &RootState) -> Expr<'static> {
    let mut f: Vec<(&'static str, Expr<'static>)> = vec![("boundOrgId", Expr::bytes(s.org_id.to_vec()))];
    for (i, n) in ROOT_SLOT_NAMES.iter().enumerate() {
        f.push((n, Expr::bytes(s.owners[i].to_vec())));
    }
    f.push(("ownerM", Expr::int(s.owner_m)));
    f.push(("emergencyK", Expr::int(s.emergency_k)));
    f.push(("recoveryM", Expr::int(s.recovery_m)));
    f.push(("frozen", Expr::byte(s.frozen as u8)));
    f.push(("rootNonce", Expr::bytes(num8(s.nonce).to_vec())));
    struct_object(f)
}

/* ---------------- root-only transactions ---------------- */

#[derive(Clone)]
struct RootCase {
    prev: RootState,
    new: RootState,
    tmpl: RootTemplate,
    /// successor compiled against a DIFFERENT template (covenant substitution)
    next_tmpl: Option<RootTemplate>,
    action: i64,
    /// slot indices that sign with their OWN key
    signers: Vec<usize>,
    /// slot index -> foreign key seed used to sign that slot
    forged: Vec<(usize, u8)>,
    /// copy the signature produced for slot .0 into slot .1 as well
    dup_slot: Option<(usize, usize)>,
    /// override the trailing sighash-type byte of one slot
    slot_type_byte: Option<(usize, u8)>,
    /// override the whole blob length
    blob_len: Option<usize>,
    sequence: u64,
    hash_type: SigHashType,
    succ_value: Option<i64>,
    /// use rootSuccession instead of rootAction; value = signing key seed
    succession: Option<u8>,
    post_sign_mutate: bool,
    budget: u16,
    /// extra data pushes at the FRONT of the sigscript (stack-headroom probe)
    stack_pad: usize,
}
impl RootCase {
    fn authorize(prev: RootState, signers: &[usize]) -> RootCase {
        let new = prev.advanced();
        RootCase {
            prev,
            new,
            tmpl: RootTemplate::default(),
            next_tmpl: None,
            action: 0,
            signers: signers.to_vec(),
            forged: vec![],
            dup_slot: None,
            slot_type_byte: None,
            blob_len: None,
            sequence: 0,
            hash_type: SIG_HASH_ALL,
            succ_value: None,
            succession: None,
            post_sign_mutate: false,
            budget: 400,
            stack_pad: 0,
        }
    }
    /// A well-formed OWNER-RECOVER: the recovery quorum installs a smaller set
    /// past the idle delay, and (decision D6) it LANDS FROZEN.
    fn recover(prev: RootState, signers: &[usize]) -> RootCase {
        let mut c = RootCase::authorize(prev.clone(), signers);
        c.action = 4;
        c.sequence = RECOVERY_DELAY as u64;
        let mut n = prev.advanced();
        n.owners[2] = ZERO32;
        n.owners[3] = ZERO32;
        n.owner_m = 2;
        n.recovery_m = 2;
        n.frozen = 1; // D6
        c.new = n;
        c
    }
    /// A well-formed SUCCESSION: the pinned key installs a new set past the
    /// idle delay, landing FROZEN and changing the primary key (D1).
    fn succeed(prev: RootState, seed: u8) -> RootCase {
        let mut c = RootCase::authorize(prev.clone(), &[]);
        c.succession = Some(seed);
        c.sequence = SUCCESSION_DELAY as u64;
        let mut n = prev.advanced();
        n.owners[0] = xonly32(&kp(0x91));
        n.frozen = 1;
        c.new = n;
        c
    }
}

struct RootOutcome {
    result: Result<(), TxScriptError>,
    units: u64,
    tx: Transaction,
    entries: Vec<UtxoEntry>,
    redeem_len: usize,
    sigscript_len: usize,
}

fn owner_blob(tx: &Transaction, entries: &[UtxoEntry], idx: usize, c: &RootCase) -> Vec<u8> {
    let mut slots: Vec<Vec<u8>> = (0..N_SLOTS).map(|_| placeholder_slot()).collect();
    for i in c.signers.iter() {
        slots[*i] = sign_type(tx, entries, idx, &kp(OWNER_SEEDS[*i]), c.hash_type);
    }
    for (slot, seed) in c.forged.iter() {
        slots[*slot] = sign_type(tx, entries, idx, &kp(*seed), c.hash_type);
    }
    if let Some((from, to)) = c.dup_slot {
        slots[to] = slots[from].clone();
    }
    if let Some((slot, byte)) = c.slot_type_byte {
        let last = slots[slot].len() - 1;
        slots[slot][last] = byte;
    }
    let mut blob: Vec<u8> = slots.into_iter().flatten().collect();
    assert_eq!(blob.len(), SIG_BLOB_LEN);
    if let Some(n) = c.blob_len {
        blob.resize(n, 0u8);
    }
    blob
}

fn run_root(c: &RootCase) -> RootOutcome {
    let prev_c = compile_root(&c.prev, &c.tmpl);
    let next_c = compile_root(&c.new, c.next_tmpl.as_ref().unwrap_or(&c.tmpl));
    let entries = vec![cov_utxo(ROOT_KAS, &prev_c, COV_ROOT)];
    let succ_value = c.succ_value.unwrap_or(ROOT_KAS - ROOT_FEE_PAID);
    let outputs = vec![cov_out(succ_value, &next_c, 0, COV_ROOT)];

    let unsigned = build_tx(vec![tx_input(1, vec![], c.sequence, c.budget)], outputs.clone());
    let sigscript = match c.succession {
        Some(seed) => {
            let mut s = sign_type(&unsigned, &entries, 0, &kp(seed), c.hash_type);
            if let Some((_, byte)) = c.slot_type_byte {
                let last = s.len() - 1;
                s[last] = byte;
            }
            cov_call(&prev_c, "rootSuccession", vec![root_state_arg(&c.new), Expr::bytes(s)])
        }
        None => {
            let blob = owner_blob(&unsigned, &entries, 0, c);
            cov_call(&prev_c, "rootAction", vec![root_state_arg(&c.new), Expr::int(c.action), Expr::bytes(blob)])
        }
    };
    let sigscript = if c.stack_pad > 0 {
        let mut pad = ScriptBuilder::new();
        for _ in 0..c.stack_pad {
            pad.add_data(&[0x01u8]).unwrap();
        }
        let mut padded = pad.drain();
        padded.extend_from_slice(&sigscript);
        padded
    } else {
        sigscript
    };
    let mut final_outputs = outputs;
    if c.post_sign_mutate {
        final_outputs[0].value -= 1;
    }
    let sigscript_len = sigscript.len();
    let tx = build_tx(vec![tx_input(1, sigscript, c.sequence, c.budget)], final_outputs);
    let (result, units) = execute_input_measured(tx.clone(), entries.clone(), 0);
    RootOutcome { result, units, tx, entries, redeem_len: prev_c.script.len(), sigscript_len }
}

fn accept_root(label: &str, c: &RootCase) -> RootOutcome {
    let o = run_root(c);
    o.result.as_ref().unwrap_or_else(|e| panic!("{label}: the root must ACCEPT this honest case: {e:?}"));
    o
}
fn refuse_root(label: &str, c: &RootCase) -> String {
    let o = run_root(c);
    match o.result {
        Ok(()) => panic!("{label}: the root ACCEPTED a case that must be refused"),
        Err(e) => format!("{e:?}"),
    }
}

/* ================================================================== */
/* state layout (section 9.1) on the PRODUCTION bytes                  */
/* ================================================================== */

#[test]
fn v7root_state_layout_is_fixed_width() {
    // The state region length must be identical for every reachable state,
    // otherwise a rooted vault cannot slice HEAD and TAIL by fixed offsets.
    let states = [
        RootState::with(1, 1, 1, 0),
        RootState::with(12, 12, 1, 6),
        RootState { frozen: 1, nonce: 1, ..RootState::with(7, 4, 2, 3) },
        RootState { nonce: i64::from(u32::MAX), ..RootState::with(3, 2, 1, 2) },
    ];
    let mut lens = vec![];
    for s in states.iter() {
        let c = compile_root(s, &RootTemplate::default());
        let t = template_of(&c);
        lens.push(t.state_len);
        let state = &c.script[c.state_layout.start..c.state_layout.start + c.state_layout.len];
        let tail = &state[state.len() - ROOT_TAIL_LEN..];
        let mut expect = vec![0x01u8, s.frozen as u8, 0x08u8];
        expect.extend_from_slice(&num8(s.nonce));
        assert_eq!(tail, &expect[..], "root TAIL bytes must be 0x01||frozen||0x08||nonce8 for {s:?}");
    }
    assert!(lens.windows(2).all(|w| w[0] == w[1]), "root state region length must be CONSTANT, got {lens:?}");
    assert_eq!(lens[0], ROOT_STATE_LEN, "measured rootStateLen");

    let c = compile_root(&RootState::with(12, 12, 1, 6), &RootTemplate::default());
    let t = template_of(&c);
    println!(
        "[layout] rootStateLen {} B (33 + 12x33 + 3x9 + 2 + 9) | TAIL_LEN {} B | head {} B | prefix {} B | suffix {} B | redeem {} B",
        t.state_len,
        ROOT_TAIL_LEN,
        t.state_len - ROOT_TAIL_LEN,
        t.prefix.len(),
        t.suffix.len(),
        c.script.len()
    );
    // The template identity a rooted vault pins at genesis. It must be
    // independent of the live state, so every state above must produce it.
    println!("[layout] rootTemplateVmHash blake2b-256(prefix || suffix) = {}", hx(&t.hash));
    for s in states.iter() {
        assert_eq!(template_of(&compile_root(s, &RootTemplate::default())).hash, t.hash, "the root template identity must not depend on the live state");
    }
}

