#[test]
fn v7root_honest_authorize_2_of_3() {
    let o = accept_root("AUTHORIZE 2-of-3", &RootCase::authorize(RootState::with(3, 2, 1, 2), &[0, 1]));
    println!("ROOT AUTHORIZE 2-of-3: units {} | redeem {} B | sigscript {} B", o.units, o.redeem_len, o.sigscript_len);
}

#[test]
fn v7root_honest_authorize_12_of_12() {
    let all: Vec<usize> = (0..12).collect();
    let o = accept_root("AUTHORIZE 12-of-12", &RootCase::authorize(RootState::with(12, 12, 1, 6), &all));
    println!("ROOT AUTHORIZE 12-of-12: units {} | redeem {} B | sigscript {} B", o.units, o.redeem_len, o.sigscript_len);
}

#[test]
fn v7root_honest_rotate_full_quorum() {
    let prev = RootState::with(3, 2, 1, 2);
    let mut c = RootCase::authorize(prev.clone(), &[0, 1]);
    c.action = 1;
    let mut new = prev.advanced();
    new.owners[2] = xonly32(&kp(0x81));
    new.owners[3] = xonly32(&kp(0x82));
    new.owner_m = 3;
    c.new = new;
    accept_root("ROTATE (full quorum)", &c);
}

#[test]
fn v7root_honest_rotate_is_allowed_while_frozen() {
    // Compromised keys must be rotatable BEFORE the organization unfreezes.
    let prev = RootState { frozen: 1, ..RootState::with(3, 2, 1, 2) };
    let mut c = RootCase::authorize(prev.clone(), &[0, 1]);
    c.action = 1;
    let mut new = prev.advanced();
    new.owners[2] = xonly32(&kp(0x81));
    c.new = new;
    accept_root("ROTATE while frozen (full quorum)", &c);
}

#[test]
fn v7root_honest_freeze_by_emergency_k_1() {
    let prev = RootState::with(3, 3, 1, 2);
    let mut c = RootCase::authorize(prev.clone(), &[1]); // ONE owner, K = 1
    c.action = 2;
    c.new = RootState { frozen: 1, ..prev.advanced() };
    accept_root("FREEZE by emergency quorum K=1", &c);
}

#[test]
fn v7root_honest_unfreeze_full_quorum() {
    let prev = RootState { frozen: 1, ..RootState::with(3, 2, 1, 2) };
    let mut c = RootCase::authorize(prev.clone(), &[0, 1]);
    c.action = 3;
    c.new = RootState { frozen: 0, ..prev.advanced() };
    accept_root("UNFREEZE (full quorum)", &c);
}

#[test]
fn v7root_honest_owner_recover_lands_frozen_after_idle_delay() {
    // DECISION D6: action 4 must land frozen = 1. The recovery quorum (2 of a
    // 4-owner set, ownerM = 4) installs a smaller set past the idle delay.
    let o = accept_root(
        "OWNER-RECOVER (recovery quorum + idle age, landing FROZEN)",
        &RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]),
    );
    println!("ROOT OWNER-RECOVER (D6, lands frozen): units {}", o.units);
}

#[test]
fn v7root_honest_succession_after_idle_delay() {
    let prev = RootState::with(3, 2, 1, 0);
    let mut c = RootCase::succeed(prev.clone(), SUCCESSOR_SEED);
    let mut new = prev.advanced();
    new.owners[0] = xonly32(&kp(0x91));
    new.owners[1] = xonly32(&kp(0x92));
    new.owners[2] = ZERO32;
    new.owner_m = 2;
    new.emergency_k = 1;
    new.recovery_m = 0;
    new.frozen = 1; // the installed set lands FROZEN by rule
    c.new = new;
    accept_root("SUCCESSION (pinned key + idle age)", &c);
}

#[test]
fn v7root_honest_nonce_rolls_over_multi_byte_boundaries() {
    // The byte[8] nonce advances as OpNum2Bin(prev + 1, 8): exercise the
    // carries a rooted vault has to reproduce byte-exactly.
    for start in [0i64, 254, 255, 65_534, 65_535, 16_777_215, i64::from(u32::MAX), 1 << 40] {
        let prev = RootState { nonce: start, ..RootState::with(3, 2, 1, 2) };
        accept_root(&format!("AUTHORIZE with nonce {start} -> {}", start + 1), &RootCase::authorize(prev, &[0, 1]));
    }
}

#[test]
fn v7root_honest_full_lifecycle_in_sequence() {
    // genesis-like state -> AUTHORIZE -> FREEZE -> ROTATE (while frozen) ->
    // UNFREEZE -> AUTHORIZE, each transition starting from the previous
    // successor state, so the nonce and the freeze flag are carried honestly.
    let mut s = RootState::with(4, 3, 1, 2);
    accept_root("lifecycle: AUTHORIZE", &RootCase::authorize(s.clone(), &[0, 1, 2]));
    s = s.advanced();

    let mut freeze = RootCase::authorize(s.clone(), &[3]);
    freeze.action = 2;
    freeze.new = RootState { frozen: 1, ..s.advanced() };
    accept_root("lifecycle: FREEZE (K=1)", &freeze);
    s = RootState { frozen: 1, ..s.advanced() };

    let mut rotate = RootCase::authorize(s.clone(), &[0, 1, 2]);
    rotate.action = 1;
    let mut rotated = s.advanced();
    rotated.owners[3] = xonly32(&kp(0x81));
    rotate.new = rotated.clone();
    accept_root("lifecycle: ROTATE while frozen", &rotate);
    s = rotated;

    let mut unfreeze = RootCase::authorize(s.clone(), &[0, 1, 2]);
    unfreeze.action = 3;
    unfreeze.new = RootState { frozen: 0, ..s.advanced() };
    accept_root("lifecycle: UNFREEZE", &unfreeze);
    s = RootState { frozen: 0, ..s.advanced() };

    accept_root("lifecycle: AUTHORIZE after the unfreeze", &RootCase::authorize(s, &[0, 1, 2]));
}

#[test]
fn v7root_honest_threshold_sweep_1_of_1_through_12_of_12() {
    // Each M-of-M accepted; each M-1 of M separately REFUSED (11 rows).
    let mut short_refusals = 0;
    for n in 1..=N_SLOTS {
        let prev = RootState::with(n, n as i64, 1, 0);
        let signers: Vec<usize> = (0..n).collect();
        accept_root(&format!("AUTHORIZE {n}-of-{n}"), &RootCase::authorize(prev.clone(), &signers));
        if n > 1 {
            let short: Vec<usize> = (0..n - 1).collect();
            refuse_root(&format!("AUTHORIZE {}-of-{n} (one short)", n - 1), &RootCase::authorize(prev, &short));
            short_refusals += 1;
        }
    }
    assert_eq!(short_refusals, 11, "the threshold sweep must contribute 11 one-signature-short refusals");
}

/* ================================================================== */
/* D6 — OWNER-RECOVER MUST LAND FROZEN (coordinator decision, s. 11)   */
/* ================================================================== */

#[test]
fn v7root_d6_owner_recover_must_land_frozen() {
    // Honest: lands frozen -> ACCEPTED (also covered above; asserted here so
    // the D6 rule is proven in one place, both directions).
    accept_root("D6 honest: OWNER-RECOVER landing FROZEN", &RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]));

    // Hostile: identical in every other respect, but landing UNFROZEN.
    let mut unfrozen = RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]);
    unfrozen.new.frozen = 0;
    let err = refuse_root("D6: OWNER-RECOVER landing UNFROZEN", &unfrozen);
    println!("D6 OWNER-RECOVER landing unfrozen -> REFUSED: {err}");

    // Hostile: a recovery that leaves the HEAD unchanged (the section 10.7
    // observation) still lands frozen, so it can never be byte-identical to an
    // AUTHORIZE successor. Landing it unfrozen — which is what would make it
    // look like an AUTHORIZE — is refused.
    let prev = RootState::with(4, 4, 1, 2);
    let mut head_unchanged = RootCase::authorize(prev.clone(), &[0, 1]);
    head_unchanged.action = 4;
    head_unchanged.sequence = RECOVERY_DELAY as u64;
    head_unchanged.new = prev.advanced(); // head preserved, frozen = 0
    let err = refuse_root("D6: OWNER-RECOVER with an unchanged head, landing unfrozen", &head_unchanged);
    println!("D6 unchanged-head recovery can no longer imitate AUTHORIZE -> REFUSED: {err}");

    // The same transition WITH the frozen landing is well-formed and accepted:
    // it is now distinguishable only from a FREEZE, whose sole vault effect is
    // the AUTHORITY-REDUCING emergency pause.
    let mut head_unchanged_frozen = head_unchanged.clone();
    head_unchanged_frozen.new = RootState { frozen: 1, ..prev.advanced() };
    accept_root("D6: OWNER-RECOVER with an unchanged head, landing FROZEN", &head_unchanged_frozen);
}

/* ================================================================== */
/* hostile matrix — every root-side row of sections 7.8 and 10.8       */
/* ================================================================== */

fn root_hostile_rows() -> Vec<(&'static str, RootCase)> {
    let base = RootState::with(3, 2, 1, 2);
    let big = RootState::with(6, 4, 2, 3);
    let mut rows: Vec<(&'static str, RootCase)> = vec![];

    rows.push(("duplicate owner key in the rotated set", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        let mut n = base.advanced();
        n.owners[2] = n.owners[0];
        c.new = n;
        c
    }));
    rows.push(("duplicate owner key in the predecessor (malformed genesis)", {
        let mut prev = RootState::with(3, 2, 1, 2);
        prev.owners[2] = prev.owners[0];
        RootCase::authorize(prev, &[0, 1])
    }));
    rows.push(("one signature replayed into a second slot", {
        let mut c = RootCase::authorize(base.clone(), &[0]);
        c.dup_slot = Some((0, 1));
        c
    }));
    rows.push(("insufficient quorum (1 of 2 required)", RootCase::authorize(base.clone(), &[0])));
    rows.push(("outsider key in an owner slot", {
        let mut c = RootCase::authorize(base.clone(), &[0]);
        c.forged = vec![(1, OUTSIDER_SEED)];
        c
    }));
    rows.push(("removed owner signing a sentinel slot", {
        let mut prev = RootState::with(3, 2, 1, 2);
        prev.owners[2] = ZERO32;
        let mut c = RootCase::authorize(prev, &[0]);
        c.forged = vec![(2, OWNER_SEEDS[2])];
        c
    }));
    rows.push(("root nonce not advanced (replay)", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.new = base.clone();
        c
    }));
    rows.push(("root nonce advanced by two", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.new = RootState { nonce: base.nonce + 2, ..base.clone() };
        c
    }));
    rows.push(("root nonce moved BACKWARD", {
        let prev = RootState { nonce: 9, ..base.clone() };
        let mut c = RootCase::authorize(prev.clone(), &[0, 1]);
        c.new = RootState { nonce: 8, ..prev };
        c
    }));
    rows.push(("boundOrgId rewritten in the successor", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.new = RootState { org_id: ORG_ID_B, ..base.advanced() };
        c
    }));
    rows.push(("owner set changed under AUTHORIZE", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        let mut n = base.advanced();
        n.owners[2] = xonly32(&kp(0x81));
        c.new = n;
        c
    }));
    rows.push(("threshold lowered under AUTHORIZE", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.new = RootState { owner_m: 1, ..base.advanced() };
        c
    }));
    rows.push(("rotation to ownerM above the active count", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        c.new = RootState { owner_m: 4, ..base.advanced() };
        c
    }));
    rows.push(("rotation to ownerM = 0", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        c.new = RootState { owner_m: 0, ..base.advanced() };
        c
    }));
    rows.push(("rotation to emergencyK above ownerM", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        c.new = RootState { emergency_k: 3, ..base.advanced() };
        c
    }));
    rows.push(("rotation to recoveryM above ownerM", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        c.new = RootState { recovery_m: 3, ..base.advanced() };
        c
    }));
    rows.push(("rotation leaving a hole in the active slots", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        let mut n = base.advanced();
        n.owners[1] = ZERO32; // slot 3 active, slot 2 inactive
        n.owner_m = 2;
        c.new = n;
        c
    }));
    rows.push(("rotation to an empty owner set", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        let mut n = base.advanced();
        n.owners = [ZERO32; N_SLOTS];
        n.owner_m = 1;
        c.new = n;
        c
    }));
    rows.push(("FREEZE quorum (K) used to ROTATE", {
        let mut c = RootCase::authorize(big.clone(), &[0, 1]); // K = 2, M = 4
        c.action = 1;
        let mut n = big.advanced();
        n.owners[5] = xonly32(&kp(0x81));
        c.new = n;
        c
    }));
    rows.push(("FREEZE quorum (K) used to UNFREEZE", {
        let frozen = RootState { frozen: 1, ..big.clone() };
        let mut c = RootCase::authorize(frozen.clone(), &[0, 1]);
        c.action = 3;
        c.new = RootState { frozen: 0, ..frozen.advanced() };
        c
    }));
    rows.push(("FREEZE quorum (K) used to OWNER-RECOVER", {
        // the lighter emergency quorum (K = 2) must not reach the recovery
        // path either: recoveryM = 3 and only 2 owners sign.
        RootCase::recover(RootState::with(4, 4, 2, 3), &[0, 1])
    }));
    rows.push(("FREEZE also changing the owner set", {
        let mut c = RootCase::authorize(base.clone(), &[0]);
        c.action = 2;
        let mut n = base.advanced();
        n.frozen = 1;
        n.owners[2] = xonly32(&kp(0x81));
        c.new = n;
        c
    }));
    rows.push(("FREEZE while already frozen", {
        let frozen = RootState { frozen: 1, ..base.clone() };
        let mut c = RootCase::authorize(frozen.clone(), &[0]);
        c.action = 2;
        c.new = RootState { frozen: 1, ..frozen.advanced() };
        c
    }));
    rows.push(("AUTHORIZE while frozen", {
        let frozen = RootState { frozen: 1, ..base.clone() };
        let mut c = RootCase::authorize(frozen.clone(), &[0, 1]);
        c.new = frozen.advanced();
        c
    }));
    rows.push(("unfreeze disguised as AUTHORIZE", {
        let frozen = RootState { frozen: 1, ..base.clone() };
        let mut c = RootCase::authorize(frozen.clone(), &[0, 1]);
        c.new = RootState { frozen: 0, ..frozen.advanced() };
        c
    }));
    rows.push(("OWNER-RECOVER before the idle delay", {
        let mut c = RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]);
        c.sequence = (RECOVERY_DELAY - 1) as u64;
        c
    }));
    rows.push(("OWNER-RECOVER with the sequence disabled bit set", {
        let mut c = RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]);
        c.sequence = (1u64 << 63) | RECOVERY_DELAY as u64;
        c
    }));
    rows.push(("OWNER-RECOVER when recovery is disabled (recoveryM = 0)", {
        let prev = RootState::with(4, 4, 1, 0);
        let mut c = RootCase::recover(prev.clone(), &[0, 1]);
        c.new = RootState { recovery_m: 0, ..c.new.clone() };
        c
    }));
    rows.push(("OWNER-RECOVER below the recovery quorum", {
        let mut c = RootCase::recover(RootState::with(4, 4, 1, 2), &[0]);
        c.new.owner_m = 1;
        c.new.recovery_m = 1;
        c
    }));
    rows.push(("OWNER-RECOVER landing UNFROZEN (decision D6)", {
        let mut c = RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1]);
        c.new.frozen = 0;
        c
    }));
    rows.push(("SUCCESSION before the idle delay", {
        let mut c = RootCase::succeed(base.clone(), SUCCESSOR_SEED);
        c.sequence = (SUCCESSION_DELAY - 1) as u64;
        c
    }));
    rows.push(("SUCCESSION signed by a non-successor key", RootCase::succeed(base.clone(), OUTSIDER_SEED)));
    rows.push(("SUCCESSION landing UNFROZEN", {
        let mut c = RootCase::succeed(base.clone(), SUCCESSOR_SEED);
        c.new.frozen = 0;
        c
    }));
    rows.push(("SUCCESSION re-installing the same primary key (deviation D1)", {
        let mut c = RootCase::succeed(base.clone(), SUCCESSOR_SEED);
        c.new.owners[0] = base.owners[0];
        c
    }));
    rows.push(("SUCCESSION when the successor key is disabled (zero)", {
        let mut c = RootCase::succeed(base.clone(), SUCCESSOR_SEED);
        c.tmpl = RootTemplate { successor_pk: ZERO32, ..RootTemplate::default() };
        c
    }));
    for (label, ht) in [
        ("owner slots signed with SIGHASH_NONE", SIG_HASH_NONE),
        ("owner slots signed with SIGHASH_SINGLE", SIG_HASH_SINGLE),
    ] {
        rows.push((label, {
            let mut c = RootCase::authorize(base.clone(), &[0, 1]);
            c.hash_type = ht;
            c
        }));
    }
    rows.push(("owner slots signed with SIGHASH_ALL|ANYONECANPAY", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.hash_type = SigHashType::from_u8(SIG_HASH_ALL.to_u8() | SIG_HASH_ANY_ONE_CAN_PAY.to_u8()).expect("allowed type");
        c
    }));
    rows.push(("owner slot with a forged 0x01 gate byte over a SIGHASH_NONE signature", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.hash_type = SIG_HASH_NONE;
        c.slot_type_byte = Some((0, 0x01));
        c
    }));
    rows.push(("succession signature with a forged 0x01 gate byte over SIGHASH_NONE", {
        let mut c = RootCase::succeed(base.clone(), SUCCESSOR_SEED);
        c.hash_type = SIG_HASH_NONE;
        c.slot_type_byte = Some((0, 0x01));
        c
    }));
    rows.push(("successor output mutated after the owners signed", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.post_sign_mutate = true;
        c
    }));
    rows.push(("owner signature blob too short", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.blob_len = Some(SIG_BLOB_LEN - 1);
        c
    }));
    rows.push(("owner signature blob too long", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.blob_len = Some(SIG_BLOB_LEN + 65);
        c
    }));
    rows.push(("action out of range (5)", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 5;
        c
    }));
    rows.push(("negative action", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = -1;
        c
    }));
    rows.push(("root value drained beyond rootMaxFeePerTx", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.succ_value = Some(ROOT_KAS - ROOT_MAX_FEE - 1);
        c
    }));
    rows.push(("successor compiled against a different root template", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.next_tmpl = Some(RootTemplate { recovery_delay: RECOVERY_DELAY + 1, ..RootTemplate::default() });
        c
    }));
    /* the retyped tail's own domain (deviation D8) */
    rows.push(("non-canonical frozen byte in the predecessor (0x02)", {
        let mut prev = RootState::with(3, 2, 1, 2);
        prev.frozen = 2;
        RootCase::authorize(prev, &[0, 1])
    }));
    rows.push(("non-canonical frozen byte in the successor (0x02, under ROTATE)", {
        let mut c = RootCase::authorize(base.clone(), &[0, 1]);
        c.action = 1;
        let mut n = base.advanced();
        n.owners[2] = xonly32(&kp(0x81));
        n.frozen = 2;
        c.new = n;
        c
    }));
    rows.push(("negative-zero frozen byte (0x80) in the predecessor", {
        let mut prev = RootState::with(3, 2, 1, 2);
        prev.frozen = 0x80;
        RootCase::authorize(prev, &[0, 1])
    }));
    rows
}

#[test]
fn v7root_hostile_matrix_all_refused() {
    let rows = root_hostile_rows();
    println!("ROOT HOSTILE MATRIX ON PRODUCTION BYTES ({} rows)", rows.len());
    for (label, case) in rows.iter() {
        let err = refuse_root(label, case);
        println!("  REFUSED  {label}\n           -> {err}");
    }
    // 47 ported rows (sections 7.8 + 10.8) + the D6 row + two new rows the
    // production candidate adds (emergency quorum reaching OWNER-RECOVER, and
    // a forged gate byte on the succession signature).
    assert!(rows.len() >= 48, "every root-side row of 7.8/10.8 plus D6 must be present (got {})", rows.len());
}

/* ================================================================== */
/* PRODUCTION-BYTE integration: the real pv_call_encoder BINARY        */
/* ================================================================== */

/// Encode a root call with the REAL `pv_call_encoder` binary (the exact tool
/// the SDK shells out to) and drive its bytes through the engine. This is the
/// production-byte rule: never only the in-process encoder, which is the blind
/// spot that shipped the v0.2 boundVaultId defect.
mod encoder {
    use super::*;
    use std::path::PathBuf;
    use std::process::Command;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn encoder_path() -> PathBuf {
        PathBuf::from(format!("{}/target/debug/pv_call_encoder", env!("CARGO_MANIFEST_DIR")))
    }

    fn tmp_dir() -> PathBuf {
        let unique = format!("{}-{}", std::process::id(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos());
        let dir = std::env::temp_dir().join(format!("pv-v7root-{unique}"));
        std::fs::create_dir_all(&dir).expect("tmp dir");
        dir
    }

    fn bytes_arg(b: &[u8]) -> serde_json::Value {
        serde_json::json!({"kind": "array", "data": b.iter().map(|x| serde_json::json!({"kind": "byte", "data": x})).collect::<Vec<_>>()})
    }
    fn int_arg(v: i64) -> serde_json::Value {
        serde_json::json!({"kind": "int", "data": v})
    }
    fn byte_arg(v: u8) -> serde_json::Value {
        serde_json::json!({"kind": "byte", "data": v})
    }

    fn ctor_args(s: &RootState, t: &RootTemplate) -> serde_json::Value {
        let mut a = vec![bytes_arg(&s.org_id)];
        for o in s.owners.iter() {
            a.push(bytes_arg(o));
        }
        a.push(int_arg(s.owner_m));
        a.push(int_arg(s.emergency_k));
        a.push(int_arg(s.recovery_m));
        a.push(byte_arg(s.frozen as u8));
        a.push(bytes_arg(&num8(s.nonce)));
        a.push(int_arg(t.recovery_delay));
        a.push(bytes_arg(&t.successor_pk));
        a.push(int_arg(t.succession_delay));
        a.push(int_arg(t.max_fee));
        serde_json::Value::Array(a)
    }

    fn successor_json(s: &RootState) -> serde_json::Value {
        let mut m = serde_json::Map::new();
        for (i, n) in ROOT_SLOT_NAMES.iter().enumerate() {
            m.insert((*n).to_string(), serde_json::Value::String(hx(&s.owners[i])));
        }
        m.insert("ownerM".into(), serde_json::json!(s.owner_m));
        m.insert("emergencyK".into(), serde_json::json!(s.emergency_k));
        m.insert("recoveryM".into(), serde_json::json!(s.recovery_m));
        m.insert("frozen".into(), serde_json::json!(s.frozen));
        m.insert("rootNonce".into(), serde_json::json!(s.nonce));
        serde_json::Value::Object(m)
    }

    /// Run the binary; `Ok(hex)` on success, `Err(stderr)` when it fails closed.
    fn run(prev: &RootState, tmpl: &RootTemplate, call: serde_json::Value) -> Result<String, String> {
        let dir = tmp_dir();
        let src = dir.join("root.sil");
        std::fs::write(&src, src_root()).unwrap();
        let args = dir.join("ctor.json");
        std::fs::write(&args, serde_json::to_string(&ctor_args(prev, tmpl)).unwrap()).unwrap();
        let cj = dir.join("call.json");
        std::fs::write(&cj, serde_json::to_string(&call).unwrap()).unwrap();
        let out = Command::new(encoder_path()).arg(&src).arg(&args).arg(&cj).output().expect("run pv_call_encoder");
        let _ = std::fs::remove_dir_all(&dir);
        if out.status.success() {
            Ok(String::from_utf8(out.stdout).unwrap().trim().to_string())
        } else {
            Err(String::from_utf8_lossy(&out.stderr).trim().to_string())
        }
    }

    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
    }

    /// Build a root-only transaction whose sigscript is the BINARY's output.
    fn execute_with_encoder(c: &RootCase, mut call: serde_json::Value) -> Result<(), TxScriptError> {
        let prev_c = compile_root(&c.prev, &c.tmpl);
        let next_c = compile_root(&c.new, &c.tmpl);
        let entries = vec![cov_utxo(ROOT_KAS, &prev_c, COV_ROOT)];
        let outputs = vec![cov_out(ROOT_KAS - ROOT_FEE_PAID, &next_c, 0, COV_ROOT)];
        let unsigned = build_tx(vec![tx_input(1, vec![], c.sequence, c.budget)], outputs.clone());
        match c.succession {
            Some(seed) => {
                let s = sign_type(&unsigned, &entries, 0, &kp(seed), c.hash_type);
                call["successorSig"] = serde_json::Value::String(hx(&s));
            }
            None => {
                let blob = owner_blob(&unsigned, &entries, 0, c);
                call["ownerSigs"] = serde_json::Value::String(hx(&blob));
            }
        }
        let encoded = run(&c.prev, &c.tmpl, call).expect("the encoder must succeed for an honest call");
        let mut sigscript = unhex(&encoded);
        sigscript.extend_from_slice(&push_redeem(&prev_c.script));
        let tx = build_tx(vec![tx_input(1, sigscript, c.sequence, c.budget)], outputs);
        execute_input_measured(tx, entries, 0).0
    }

    #[test]
    fn v7root_encoder_production_bytes_accepted_by_the_engine() {
        assert!(encoder_path().exists(), "build it first: cd tests/vm && cargo build --bin pv_call_encoder");

        for (label, case) in [
            ("rootAction AUTHORIZE 2-of-3", RootCase::authorize(RootState::with(3, 2, 1, 2), &[0, 1])),
            ("rootAction AUTHORIZE 12-of-12", RootCase::authorize(RootState::with(12, 12, 1, 6), &(0..12).collect::<Vec<_>>())),
            ("rootAction OWNER-RECOVER (D6, lands frozen)", RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1])),
        ] {
            let call = serde_json::json!({
                "contractVersion": "policyvault-0.7-root",
                "function": "rootAction",
                "action": case.action,
                "successor": successor_json(&case.new),
            });
            execute_with_encoder(&case, call).unwrap_or_else(|e| panic!("{label}: production encoder bytes must be accepted: {e:?}"));
            println!("  ENCODER -> ENGINE ACCEPTED  {label}");
        }

        // ROTATE and FREEZE through the same binary
        let prev = RootState::with(3, 2, 1, 2);
        let mut rotate = RootCase::authorize(prev.clone(), &[0, 1]);
        rotate.action = 1;
        let mut n = prev.advanced();
        n.owners[2] = xonly32(&kp(0x81));
        rotate.new = n;
        execute_with_encoder(
            &rotate,
            serde_json::json!({
                "contractVersion": "policyvault-0.7-root", "function": "rootAction",
                "action": 1, "successor": successor_json(&rotate.new)
            }),
        )
        .expect("rootAction ROTATE production bytes");
        println!("  ENCODER -> ENGINE ACCEPTED  rootAction ROTATE");

        let succ = RootCase::succeed(RootState::with(3, 2, 1, 0), SUCCESSOR_SEED);
        execute_with_encoder(
            &succ,
            serde_json::json!({
                "contractVersion": "policyvault-0.7-root", "function": "rootSuccession",
                "successor": successor_json(&succ.new)
            }),
        )
        .expect("rootSuccession production bytes");
        println!("  ENCODER -> ENGINE ACCEPTED  rootSuccession");
    }

    #[test]
    fn v7root_encoder_fails_closed_on_out_of_domain_intent() {
        assert!(encoder_path().exists(), "build it first: cd tests/vm && cargo build --bin pv_call_encoder");
        let prev = RootState::with(3, 2, 1, 2);
        let tmpl = RootTemplate::default();
        let ok_blob = hx(&[0u8; SIG_BLOB_LEN]);

        let base = |extra: serde_json::Value| -> serde_json::Value {
            let mut v = serde_json::json!({
                "contractVersion": "policyvault-0.7-root",
                "function": "rootAction",
                "action": 0,
                "ownerSigs": ok_blob.clone(),
                "successor": successor_json(&prev.advanced()),
            });
            for (k, val) in extra.as_object().unwrap() {
                v[k] = val.clone();
            }
            v
        };
        let successor_with = |field: &str, value: serde_json::Value| -> serde_json::Value {
            let mut s = successor_json(&prev.advanced());
            s[field] = value;
            serde_json::json!({ "successor": s })
        };

        for (label, call) in [
            ("action out of range (5)", base(serde_json::json!({"action": 5}))),
            ("negative action", base(serde_json::json!({"action": -1}))),
            ("owner blob one byte short", base(serde_json::json!({"ownerSigs": hx(&[0u8; SIG_BLOB_LEN - 1])}))),
            ("a 65-byte `signature` field instead of the blob", base(serde_json::json!({"signature": hx(&[0u8; 65])}))),
            ("unknown entrypoint", base(serde_json::json!({"function": "rootDissolve"}))),
            ("successor frozen byte out of domain", base(successor_with("frozen", serde_json::json!(2)))),
            ("successor emergencyK above ownerM", base(successor_with("emergencyK", serde_json::json!(3)))),
            ("successor recoveryM above ownerM", base(successor_with("recoveryM", serde_json::json!(9)))),
            ("successor rootNonce negative", base(successor_with("rootNonce", serde_json::json!(-1)))),
        ] {
            let err = run(&prev, &tmpl, call).expect_err(&format!("{label}: the encoder must FAIL CLOSED"));
            println!("  ENCODER FAILED CLOSED  {label}\n           -> {err}");
        }

        // An unknown contractVersion is never routed to a default. The row
        // carries a well-formed 65-byte `signature` so it reaches the version
        // dispatch rather than stopping at the shared signature field that
        // every pre-v0.7 generation requires.
        let mut unknown = base(serde_json::json!({"signature": hx(&[0u8; 65])}));
        unknown["contractVersion"] = serde_json::json!("policyvault-0.7-rooot");
        let err = run(&prev, &tmpl, unknown).expect_err("an unknown contractVersion must fail closed");
        assert!(err.contains("unknown contractVersion") && err.contains("failing closed"), "unknown version must fail closed, got: {err}");
        println!("  ENCODER FAILED CLOSED  unknown contractVersion\n           -> {err}");
    }
}

/* ================================================================== */
/* measurement, standardness and stack headroom                        */
/* ================================================================== */

fn mass_of(tx: &Transaction, entries: &[UtxoEntry]) -> (u64, u64, u64, u64) {
    let mc = MassCalculator::new(1, 10, STORAGE_MASS_PARAMETER);
    let m = mc.calc_non_contextual_masses(tx);
    let populated = PopulatedTransaction::new(tx, entries.to_vec());
    let storage = mc.calc_contextual_masses(&populated).map(|c| c.storage_mass).unwrap_or(0);
    let size = transaction_estimated_serialized_size(tx) as u64;
    (size, m.compute_mass, m.transient_mass, storage)
}

fn priced_units_and_sigops(tx: &Transaction, entries: &[UtxoEntry]) -> Vec<(u64, u16, u64)> {
    (0..tx.inputs.len())
        .map(|i| {
            let (r, priced) = execute_input_measured_priced(tx.clone(), entries.to_vec(), i, 1000);
            r.unwrap_or_else(|e| panic!("priced input {i} must accept: {e:?}"));
            let budget = ComputeBudget::checked_covering_script_units(ScriptUnits(priced)).expect("budget").0;
            let sigops = post_toccata_p2sh_sig_scanner(&tx.inputs[i].signature_script, &entries[i].script_public_key);
            (priced, budget, sigops)
        })
        .collect()
}

const MAX_STACK_PROBE: usize = 244;

/// Smallest front-padding that turns the failure into StackSizeExceeded;
/// peak combined stack = 245 - that count.
fn measure_peak_stack<F>(label: &str, mut run_with_pad: F) -> usize
where
    F: FnMut(usize) -> Result<(), TxScriptError>,
{
    run_with_pad(0).unwrap_or_else(|e| panic!("{label}: unpadded run must accept: {e:?}"));
    for pad in 1..=MAX_STACK_PROBE {
        if let Err(TxScriptError::StackSizeExceeded(size, max)) = run_with_pad(pad) {
            assert_eq!(max, 244, "{label}: unexpected MAX_STACK_SIZE");
            let peak = 245 - pad;
            println!("  {label}: peak combined stack {peak} (StackSizeExceeded at pad {pad}, reported {size}/{max}) -> headroom {}", 244 - peak);
            return peak;
        }
    }
    panic!("{label}: never hit MAX_STACK_SIZE within {MAX_STACK_PROBE} padding items");
}

#[test]
fn v7root_measurement_standardness_and_stack() {
    println!("\n===== v0.7-root PRODUCTION MEASUREMENT (real TxScriptEngine, rusty-kaspa 2.0.1) =====");

    let full = RootState::with(12, 12, 1, 6);
    let root_c = compile_root(&full, &RootTemplate::default());
    let t = template_of(&root_c);
    println!("\n[1] ROOT COVENANT GEOMETRY (production candidate)");
    println!(
        "  redeem {} B | state region {} B | head {} B | TAIL {} B | prefix {} B | suffix {} B",
        root_c.script.len(),
        t.state_len,
        t.state_len - ROOT_TAIL_LEN,
        ROOT_TAIL_LEN,
        t.prefix.len(),
        t.suffix.len()
    );
    assert_eq!(t.state_len, ROOT_STATE_LEN);

    let all: Vec<usize> = (0..12).collect();
    let auth12 = accept_root("AUTHORIZE 12-of-12", &RootCase::authorize(full.clone(), &all));
    println!("\n[2] ROOT-ONLY TRANSACTIONS");
    println!("  AUTHORIZE 12-of-12: sigscript {} B | script units {}", auth12.sigscript_len, auth12.units);

    for (label, case) in [
        ("ROTATE 12-of-12", {
            let mut c = RootCase::authorize(full.clone(), &all);
            c.action = 1;
            let mut n = full.advanced();
            n.owners[11] = xonly32(&kp(0x83));
            c.new = n;
            c
        }),
        ("AUTHORIZE 2-of-3", RootCase::authorize(RootState::with(3, 2, 1, 2), &[0, 1])),
        ("FREEZE K=1", {
            let prev = RootState::with(3, 3, 1, 2);
            let mut c = RootCase::authorize(prev.clone(), &[1]);
            c.action = 2;
            c.new = RootState { frozen: 1, ..prev.advanced() };
            c
        }),
        ("OWNER-RECOVER (D6)", RootCase::recover(RootState::with(4, 4, 1, 2), &[0, 1])),
        ("SUCCESSION", RootCase::succeed(RootState::with(3, 2, 1, 0), SUCCESSOR_SEED)),
    ] {
        let o = accept_root(label, &case);
        let (size, compute, transient, storage) = mass_of(&o.tx, &o.entries);
        let priced = priced_units_and_sigops(&o.tx, &o.entries);
        let normalized_transient = (transient * 500_000).div_ceil(1_000_000);
        println!(
            "  {label}: tx {size} B | sigscript {} B | units {} | priced {} -> budget {} | compute_mass {compute} | transient_mass {transient} | storage_mass {storage} | fee_mass {} | STATIC SIG-OPS {}",
            o.tx.inputs[0].signature_script.len(),
            o.units,
            priced[0].0,
            priced[0].1,
            compute.max(normalized_transient),
            priced[0].2
        );
        /* standardness (rusty-kaspa mining/src/mempool/check_transaction_standard.rs):
         *  - static P2SH sig-ops per input <= 15;
         *  - every output script class standard;
         *  - post-Toccata per-transaction block-fit limits: compute <= 500,000,
         *    transient <= 1,000,000. The PRE-Toccata 100,000 standard cap is
         *    reported, never asserted: covenant transactions cannot exist on a
         *    pre-Toccata network. */
        assert_eq!(priced[0].2, ROOT_STATIC_SIG_OPS, "{label}: root static sig-ops must be exactly 12 counting + 1 succession");
        assert!(priced[0].2 <= MAX_STANDARD_P2SH_SIG_OPS, "{label}: sig-ops must stay inside the standardness budget");
        for (i, out) in o.tx.outputs.iter().enumerate() {
            assert_ne!(ScriptClass::from_script(&out.script_public_key), ScriptClass::NonStandard, "{label}: output {i} must be standard");
        }
        assert!(compute <= 500_000, "{label}: compute mass {compute} exceeds the post-Toccata block-fit limit");
        assert!(transient <= 1_000_000, "{label}: transient mass {transient} exceeds the post-Toccata block-fit limit");
        if transient > 100_000 || compute > 100_000 {
            println!("    note: {label} exceeds the PRE-Toccata 100,000 standard cap — post-Toccata only");
        }
    }

    println!("\n[3] THRESHOLD SWEEP (root AUTHORIZE, M-of-M) — sigscript is CONSTANT, only compute varies");
    println!("  {:>7} | {:>13} | {:>12} | {:>13}", "M-of-N", "sigscript B", "script units", "priced units");
    let mut sig_lens = vec![];
    for n in 1..=N_SLOTS {
        let prev = RootState::with(n, n as i64, 1, 0);
        let signers: Vec<usize> = (0..n).collect();
        let o = accept_root(&format!("{n}-of-{n}"), &RootCase::authorize(prev, &signers));
        let p = priced_units_and_sigops(&o.tx, &o.entries);
        println!("  {:>7} | {:>13} | {:>12} | {:>13}", format!("{n}-of-{n}"), o.sigscript_len, o.units, p[0].0);
        sig_lens.push(o.sigscript_len);
    }
    assert!(sig_lens.windows(2).all(|w| w[0] == w[1]), "abstaining slots carry a placeholder, so the envelope must be constant");

    println!("\n[4] MAX_STACK_SIZE (244) HEADROOM");
    measure_peak_stack("root rootAction ROTATE 12-of-12 (WF(prev) + counting + WF(new))", |pad| {
        let mut c = RootCase::authorize(full.clone(), &all);
        c.action = 1;
        let mut n = full.advanced();
        n.owners[11] = xonly32(&kp(0x83));
        c.new = n;
        c.stack_pad = pad;
        run_root(&c).result
    });
    measure_peak_stack("root rootSuccession (WF(prev) + WF(new))", |pad| {
        let mut c = RootCase::succeed(RootState::with(12, 12, 1, 6), SUCCESSOR_SEED);
        c.stack_pad = pad;
        run_root(&c).result
    });
    println!("=====================================================================================\n");
}
